-- Generated by scripts/gen-schema-sql.js — edit lib/schema.js, not this file.
--
-- Paste this into your database provider's SQL editor and press Run. It does
-- the same thing as `npm run setup-db` and the "Set up database" button in
-- /admin, so you don't need a terminal to set the database up.
--
-- Safe to run more than once: every statement is IF NOT EXISTS.

-- Your invite list. Optional — leave it empty and anyone with the link can
-- RSVP. Fill it in and you get per-party seat limits, invite codes, and
-- reminder emails to whoever has not replied.
CREATE TABLE IF NOT EXISTS guests (
  id           SERIAL PRIMARY KEY,
  party_name   TEXT NOT NULL,
  email        TEXT,
  invite_code  TEXT UNIQUE,
  max_guests   INT NOT NULL DEFAULT 1,
  created_at   TIMESTAMPTZ DEFAULT NOW()
);

-- One row per party that replies. Each named guest lives in `attendees`
-- with their own meal choice and dietary note, so a party of four is one
-- row and four chairs.
CREATE TABLE IF NOT EXISTS rsvps (
  id            SERIAL PRIMARY KEY,
  guest_id      INT REFERENCES guests(id) ON DELETE SET NULL,
  party_name    TEXT NOT NULL,
  email         TEXT NOT NULL,
  attending     BOOLEAN NOT NULL,
  attendees     JSONB NOT NULL DEFAULT '[]'::jsonb,
  song_request  TEXT,
  note          TEXT,
  created_at    TIMESTAMPTZ DEFAULT NOW(),
  updated_at    TIMESTAMPTZ DEFAULT NOW()
);

-- Stops the daily reminder job from mailing the same person the same thing
-- twice, even if it fires more than once.
CREATE TABLE IF NOT EXISTS email_log (
  id      SERIAL PRIMARY KEY,
  email   TEXT NOT NULL,
  kind    TEXT NOT NULL,
  sent_at TIMESTAMPTZ DEFAULT NOW()
);

-- index: one reminder per person per kind
CREATE UNIQUE INDEX IF NOT EXISTS idx_email_log_once ON email_log(email, kind);

-- index: RSVP lookup by email
CREATE INDEX IF NOT EXISTS idx_rsvps_email ON rsvps(lower(email));
